const raw=$json.sync_context;
const ctx=typeof raw==='string'?JSON.parse(raw):raw;
if(!ctx || ctx.connector_key!=='salesforce_primary' || ctx.connector_type!=='salesforce'){
  throw new Error('SALESFORCE_SYNC_CONTEXT_INVALID');
}
let gate=ctx.reliability_gate;
if(typeof gate==='string') gate=JSON.parse(gate);
const allowed=gate?.allowed===true;
const q=v=>String(v).replace(/'/g,"\\'");
const start=new Date(ctx.query_start_at).toISOString();
const end=new Date(ctx.query_end_at).toISOString();
const fields=[
  'Id','Name','Amount','StageName','OwnerId','LeadSource',
  'CreatedDate','CloseDate','LastModifiedDate',
  'Primary_Need__c','Decision_Maker_Confirmed__c','Lost_Reason__c',
  'Implementation_Priority__c','Won_Date__c','Lost_Date__c','High_Value__c'
];
return {
  sync_context:ctx,
  should_sync:allowed,
  skip_reason:allowed?null:'RELIABILITY_CIRCUIT_OPEN',
  soql:'SELECT '+fields.join(',')+
    " FROM Opportunity WHERE LastModifiedDate >= "+start+
    " AND LastModifiedDate <= "+end+
    ' ORDER BY LastModifiedDate ASC LIMIT 2000'
};

const contextRaw=$('DB | Load Salesforce Sync Context').first().json.sync_context;
const ctx=typeof contextRaw==='string'?JSON.parse(contextRaw):contextRaw;
const page=$input.first()?.json ?? {};
if(page.done!==true || page.nextRecordsUrl){
  throw new Error('SALESFORCE_SYNC_WINDOW_LIMIT_EXCEEDED');
}
const results=Array.isArray(page.records)?page.records:[];
if(results.length>2000) throw new Error('SALESFORCE_SYNC_RESULT_LIMIT_EXCEEDED');
const expectedCurrency=String(ctx.currency_code??'').trim().toUpperCase();
const stageMap={
  'Discovery':'open',
  'Technical Review':'open',
  'Proposal Sent':'open',
  'Negotiation':'open',
  'Closed Won':'won',
  'Closed Lost':'lost'
};
const parseTimestamp=v=>{
  if(v===null||v===undefined||v==='') return null;
  const s=String(v);
  const normalized=/^\d{4}-\d{2}-\d{2}$/.test(s)?s+'T00:00:00.000Z':s;
  const d=new Date(normalized);
  return Number.isNaN(d.getTime())?null:d.toISOString();
};
const records=[];
let rejectedCount=0;
let earliestRejectedAt=null;
for(const r of results){
  const id=String(r?.Id??'').trim();
  const amountRaw=r?.Amount;
  const amount=amountRaw===null||amountRaw===undefined||amountRaw===''?NaN:Number(amountRaw);
  const stageName=String(r?.StageName??'').trim();
  const stageCategory=stageMap[stageName]??null;
  const updatedAt=parseTimestamp(r?.LastModifiedDate);
  const createdAt=parseTimestamp(r?.CreatedDate);
  const closeDate=parseTimestamp(r?.CloseDate);
  const wonDate=parseTimestamp(r?.Won_Date__c);
  const lostDate=parseTimestamp(r?.Lost_Date__c);
  const closedAt=stageCategory==='won'?(wonDate??closeDate):(stageCategory==='lost'?(lostDate??closeDate):null);
  const valid=
    id.length>0 && id.length<=200 &&
    Number.isFinite(amount) && amount>=0 &&
    /^[A-Z]{3}$/.test(expectedCurrency) &&
    stageCategory!==null &&
    updatedAt!==null &&
    (stageCategory==='open' || closedAt!==null);
  if(!valid){
    rejectedCount+=1;
    const candidate=updatedAt?new Date(updatedAt).getTime():null;
    if(candidate!==null && (earliestRejectedAt===null || candidate<earliestRejectedAt)) earliestRejectedAt=candidate;
    continue;
  }
  records.push({
    source_record_id:id,
    source_payload:{
      Name:r.Name??null,
      Amount:String(amount),
      CurrencyIsoCode:expectedCurrency,
      StageName:stageName,
      OwnerId:r.OwnerId??null,
      LeadSource:r.LeadSource??null,
      CreatedDate:createdAt,
      CloseDate:closeDate,
      LastModifiedDate:updatedAt,
      Primary_Need__c:r.Primary_Need__c??null,
      Decision_Maker_Confirmed__c:r.Decision_Maker_Confirmed__c??null,
      Lost_Reason__c:r.Lost_Reason__c??null,
      Implementation_Priority__c:r.Implementation_Priority__c??null,
      Won_Date__c:wonDate,
      Lost_Date__c:lostDate,
      High_Value__c:r.High_Value__c??null
    }
  });
}
const queryStart=new Date(ctx.query_start_at).getTime();
const queryEnd=new Date(ctx.query_end_at).getTime();
let watermarkMs=queryEnd;
if(rejectedCount>0) watermarkMs=earliestRejectedAt===null?queryStart:Math.max(queryStart,earliestRejectedAt);
return [{json:{
  connector_key:'salesforce_primary',
  query_start_at:new Date(queryStart).toISOString(),
  query_end_at:new Date(queryEnd).toISOString(),
  watermark:new Date(watermarkMs).toISOString(),
  source_count:results.length,
  record_count:records.length,
  rejected_count:rejectedCount,
  records,
  event_id:'SALESFORCE-SYNC-'+String(queryEnd)
}}];
